import test from 'node:test';import assert from 'node:assert/strict';import {correctFieldVisual,assertFieldStatusProof}from './catalogue-field-status.mjs';
test('custom-invalid appearance rejects native green success, neutral borders and muted inline errors',()=>{const good=[{greenVisible:false,border:'rgb(189, 67, 60)',errorColor:'rgb(166, 50, 45)'}];assert.equal(correctFieldVisual(good),true);assert.equal(correctFieldVisual([]),false);for(const [key,value]of [['greenVisible',true],['border','rgb(200, 212, 205)'],['errorColor','rgb(104, 118, 111)']])assert.equal(correctFieldVisual([{...good[0],[key]:value}]),false);});
const proof=()=>({formFieldStatusOldRed:[320,1280].map(width=>({width,ref:'f9df539cee3033cd444b21a9d55dbc2c363a3675',status:'expected-failure',greenVisible:true,borderMismatch:true,inlineColorMismatch:true})),formFieldLifecycle:[320,1280].flatMap(width=>['latin','phone'].map(kind=>({width,kind,status:'passed',focusedErrorRed:true,clearedOnEdit:true,restoredOnRevalidate:true,sameStep:true,notSubmitted:true})))});
test('field-status gate requires both pinned old CSS failures and four real edit/revalidation cycles',()=>{assert.doesNotThrow(()=>assertFieldStatusProof(proof()));for(const key of ['focusedErrorRed','clearedOnEdit','restoredOnRevalidate','sameStep','notSubmitted']){const bad=proof();bad.formFieldLifecycle[0][key]=false;assert.throws(()=>assertFieldStatusProof(bad));}const missing=proof();missing.formFieldLifecycle.pop();assert.throws(()=>assertFieldStatusProof(missing));const stale=proof();stale.formFieldStatusOldRed[0].ref='main';assert.throws(()=>assertFieldStatusProof(stale));const falseRed=proof();falseRed.formFieldStatusOldRed[0].greenVisible=false;assert.throws(()=>assertFieldStatusProof(falseRed));});
